import{_ as l,o as a,c as s,ag as o}from"./chunks/framework.D2veAa-g.js";const h=JSON.parse('{"title":"构件与中间件","description":"","frontmatter":{"title":"构件与中间件"},"headers":[],"relativePath":"综合知识/系统基础/操作系统/构件与中间件.md","filePath":"综合知识/系统基础/操作系统/构件与中间件.md","lastUpdated":null}'),i={name:"综合知识/系统基础/操作系统/构件与中间件.md"};function r(e,t,d,n,c,p){return a(),s("div",null,[...t[0]||(t[0]=[o('<h2 id="考点清单" tabindex="-1">考点清单 <a class="header-anchor" href="#考点清单" aria-label="Permalink to &quot;考点清单&quot;">​</a></h2><ul><li>[ ] COP（面向构件编程）基本支持</li><li>[ ] CORBA 体系结构</li><li>[ ] EJB 三种 Bean 类型</li><li>[ ] J2EE 五种构件模型</li><li>[ ] 中间件基本功能</li><li>[ ] 中间件分类与位置</li><li>[ ] 构件核心特性与标准</li></ul><h2 id="笔记" tabindex="-1">笔记 <a class="header-anchor" href="#笔记" aria-label="Permalink to &quot;笔记&quot;">​</a></h2><h3 id="cop-基本支持" tabindex="-1">COP 基本支持 <a class="header-anchor" href="#cop-基本支持" aria-label="Permalink to &quot;COP 基本支持&quot;">​</a></h3><blockquote><p>🎯 一句话结论：COP 的四个基本支持是<strong>多态性、模块封装性、后期绑定和装载、安全性</strong>。</p></blockquote><p>面向构件编程关注如何构建面向构件的解决方案，需要语言级和运行环境级的支持，核心是让构件能够独立开发、独立部署、动态组装。</p><h3 id="corba-体系结构" tabindex="-1">CORBA 体系结构 <a class="header-anchor" href="#corba-体系结构" aria-label="Permalink to &quot;CORBA 体系结构&quot;">​</a></h3><blockquote><p>🎯 一句话结论：CORBA 的&quot;软总线&quot;是 <strong>ORB（对象请求代理）</strong>，真正干活的是 <strong>Servant（伺服对象）</strong>，协调底层传输的是 <strong>POA（可移植对象适配器）</strong>。</p></blockquote><table tabindex="0"><thead><tr><th>组件</th><th>职责</th><th>记忆口诀</th></tr></thead><tbody><tr><td><strong>ORB</strong></td><td>对象请求代理，软总线，负责传递请求</td><td>总调度</td></tr><tr><td><strong>Servant</strong></td><td>CORBA 对象的真正实现，完成客户端请求</td><td>干活的</td></tr><tr><td><strong>POA</strong></td><td>在底层传输平台与接收调用并返回结果的对象实现之间协调</td><td>中间协调员</td></tr><tr><td><strong>适配器激活器</strong></td><td>管理 POA 的生命周期</td><td>管 POA 的</td></tr></tbody></table><blockquote><p>CORBA 由 <strong>OMG 组织</strong>制定，支持<strong>跨语言、跨平台</strong>分布式对象集成。</p></blockquote><h3 id="ejb-三种-bean" tabindex="-1">EJB 三种 Bean <a class="header-anchor" href="#ejb-三种-bean" aria-label="Permalink to &quot;EJB 三种 Bean&quot;">​</a></h3><blockquote><p>🎯 一句话结论：<strong>Session Bean（会话交互）→ Entity Bean（数据持久化）→ Message-Driven Bean（异步消息）</strong>。</p></blockquote><table tabindex="0"><thead><tr><th>类型</th><th>功能</th><th>关键特征</th></tr></thead><tbody><tr><td><strong>会话型 Bean (Session Bean)</strong></td><td>完成服务端与客户端的交互</td><td>维护短暂会话，会话结束数据消失</td></tr><tr><td><strong>实体型 Bean (Entity Bean)</strong></td><td>数据持久化，简化数据库开发</td><td>持久化数据</td></tr><tr><td><strong>消息驱动 Bean (Message-Driven Bean)</strong></td><td>处理并发和异步访问操作</td><td>⚠️ <strong>异步</strong>接收消息（不是同步！）</td></tr></tbody></table><h3 id="j2ee-五种构件模型" tabindex="-1">J2EE 五种构件模型 <a class="header-anchor" href="#j2ee-五种构件模型" aria-label="Permalink to &quot;J2EE 五种构件模型&quot;">​</a></h3><blockquote><p>🎯 一句话结论：J2EE 的五种构件模型是 <strong>Applet、Servlet、JSP、EJB、Application Client</strong>。</p></blockquote><table tabindex="0"><thead><tr><th>构件</th><th>运行位置</th></tr></thead><tbody><tr><td>Applet</td><td>客户端浏览器</td></tr><tr><td>Application Client</td><td>客户端</td></tr><tr><td>Servlet</td><td>服务端</td></tr><tr><td>JSP</td><td>服务端</td></tr><tr><td>EJB</td><td>服务端业务逻辑</td></tr></tbody></table><p>⚠️ 常见混淆：JNDI、IIOP、RMI 是<strong>通信协议/API</strong>，不是构件模型；JDBC 是数据库 API；JCA 是连接器架构。</p><h3 id="中间件基本功能" tabindex="-1">中间件基本功能 <a class="header-anchor" href="#中间件基本功能" aria-label="Permalink to &quot;中间件基本功能&quot;">​</a></h3><blockquote><p>🎯 一句话结论：中间件的三大基本功能 — <strong>连接和通信</strong>、<strong>交易管理机制</strong>（事务一致性）、<strong>负载均衡和高可用性</strong>。</p></blockquote><table tabindex="0"><thead><tr><th>功能</th><th>说明</th></tr></thead><tbody><tr><td>连接和通信</td><td>为客户端和服务器之间提供连接和通信</td></tr><tr><td>交易管理机制</td><td>保证交易的一致性</td></tr><tr><td>负载均衡和高可用性</td><td>提供应用的负载均衡和高可用性</td></tr></tbody></table><p><strong>中间件位置</strong>：操作系统之上、应用软件之下（OS → 中间件 → 应用）。</p><h3 id="中间件分类" tabindex="-1">中间件分类 <a class="header-anchor" href="#中间件分类" aria-label="Permalink to &quot;中间件分类&quot;">​</a></h3><blockquote><p>🎯 一句话结论：通信中间件实现<strong>跨平台通信</strong>，事务中间件实现<strong>并发事务处理</strong>，Web 服务器中间件提供 <strong>Web 运行时容器</strong>（非数据加密）。</p></blockquote><table tabindex="0"><thead><tr><th>类型</th><th>主要功能</th><th>示例</th></tr></thead><tbody><tr><td>通信（消息）中间件</td><td>保证系统在不同平台之间通信</td><td>—</td></tr><tr><td>事务中间件</td><td>并发事务处理</td><td>—</td></tr><tr><td>Web 服务器中间件</td><td>提供 Web 应用的运行时环境</td><td><strong>Tomcat</strong></td></tr><tr><td>安全中间件</td><td>加密和认证</td><td>—</td></tr></tbody></table><p>⚠️ 易错：Tomcat 是 Web 服务器中间件（提供运行时容器），不是做数据加密的。</p><h3 id="构件核心特性" tabindex="-1">构件核心特性 <a class="header-anchor" href="#构件核心特性" aria-label="Permalink to &quot;构件核心特性&quot;">​</a></h3><blockquote><p>🎯 一句话结论：构件是<strong>自包容</strong>的程序集，<strong>必须通过接口访问</strong>，<strong>不能直接操作内部</strong>，包含一组需要<strong>同时部署</strong>的原子构件。</p></blockquote><table tabindex="0"><thead><tr><th>特性</th><th>说明</th></tr></thead><tbody><tr><td>自包容</td><td>构件是自包容的程序集</td></tr><tr><td>接口访问</td><td>构件必须通过接口访问，封装内部实现</td></tr><tr><td>可重用</td><td>构件具有可重用性</td></tr><tr><td>部署</td><td>构件可单独部署，原子构件不能单独部署</td></tr><tr><td>不可直接操作内部</td><td>❌ 不能直接操作构件内部实现</td></tr></tbody></table><h3 id="构件三大标准对比" tabindex="-1">构件三大标准对比 <a class="header-anchor" href="#构件三大标准对比" aria-label="Permalink to &quot;构件三大标准对比&quot;">​</a></h3><table tabindex="0"><thead><tr><th>标准</th><th>制定组织</th><th>特点</th></tr></thead><tbody><tr><td><strong>CORBA</strong></td><td>OMG</td><td>跨语言、跨平台分布式对象集成</td></tr><tr><td><strong>COM/DCOM</strong></td><td>Microsoft</td><td>Windows 平台构件标准</td></tr><tr><td><strong>EJB</strong></td><td>Sun/Oracle</td><td>Java 企业级构件</td></tr></tbody></table><h2 id="练习题" tabindex="-1">练习题 <a class="header-anchor" href="#练习题" aria-label="Permalink to &quot;练习题&quot;">​</a></h2><p><strong>[Q4] COP基本支持</strong></p><p>面向构件的编程(COP)关注于如何支持建立面向构件的解决方案。面向构件的编程所需要的基本支持包括（ ）。</p><ul><li>A. 继承性、构件管理和绑定、构件标识、访问控制</li><li>B. 封装性、信息隐藏、独立部署、模块安全性</li><li>C. 多态性、模块封装性、后期绑定和装载、安全性</li><li>D. 构件抽象、可替代性、类型安全性、事务管理</li></ul><details class="callout callout-note"><summary class="callout-title"><span class="callout-icon">📝</span>答案与解析</summary><div class="callout-body"><p>答案：C</p><p>解析：COP基本支持=多态性+模块封装性+后期绑定和装载+安全性。</p></div></details><hr><p><strong>[Q6] 构件描述</strong></p><p>关于构件的描述，正确的是（ ）。</p><ul><li>A. 构件包含了一组需要同时部署的原子构件</li><li>B. 构件可以单独部署，原子构件不能被单独部署</li><li>C. 一个原子构件可以同时在多个构件家族中共享</li><li>D. 一个模块可以看作带有单独资源的原子构件</li></ul><details class="callout callout-note"><summary class="callout-title"><span class="callout-icon">📝</span>答案与解析</summary><div class="callout-body"><p>答案：A</p><p>解析：构件包含一组需同时部署的原子构件；构件可单独部署但原子构件不能。</p></div></details><hr><p><strong>[Q80] 构件特性</strong></p><p>关于软件构件的特性，下列说法错误的是（ ）。</p><ul><li>A. 构件是自包容的程序集</li><li>B. 构件必须通过接口访问</li><li>C. 可以直接操作构件内部</li><li>D. 构件具有可重用性</li></ul><details class="callout callout-note"><summary class="callout-title"><span class="callout-icon">📝</span>答案与解析</summary><div class="callout-body"><p>答案：C</p><p>解析：构件封装内部实现，不能直接操作内部，必须通过接口访问。</p></div></details><hr><p><strong>[Q12] CORBA伺服对象</strong></p><p>CORBA服务端构件模型中，（ ）是CORBA对象的真正实现，负责完成客户端请求。</p><ul><li>A. 伺服对象（Servant）</li><li>B. 对象适配器（Object Adapter）</li><li>C. 对象请求代理（Object Request Broker）</li><li>D. 适配器激活器（Adapter Activator）</li></ul><details class="callout callout-note"><summary class="callout-title"><span class="callout-icon">📝</span>答案与解析</summary><div class="callout-body"><p>答案：A</p><p>解析：Servant=最终完成请求的对象实现；ORB=软总线；POA=协调传输与实现。</p></div></details><hr><p><strong>[Q5] CORBA POA</strong></p><p>CORBA构件模型中，（ ）的作用是在底层传输平台与接收调用并返回结果的对象实现之间进行协调。</p><ul><li>A. 伺服对象激活器</li><li>B. 适配器激活器</li><li>C. 伺服对象定位器</li><li>D. 可移植对象适配器POA</li></ul><details class="callout callout-note"><summary class="callout-title"><span class="callout-icon">📝</span>答案与解析</summary><div class="callout-body"><p>答案：D</p><p>解析：POA=传输平台与对象实现间的协调者。</p></div></details><hr><p><strong>[Q79] CORBA软总线</strong></p><p>CORBA架构中，作为&quot;软总线&quot;的是（ ）。</p><ul><li>A. 公共设施</li><li>B. 公共对象服务</li><li>C. 对象请求代理</li><li>D. 对象适配器</li></ul><details class="callout callout-note"><summary class="callout-title"><span class="callout-icon">📝</span>答案与解析</summary><div class="callout-body"><p>答案：C</p><p>解析：ORB(Object Request Broker)=CORBA核心，相当于软总线，负责透明传递请求。</p></div></details><hr><p><strong>[Q108] CORBA标准</strong></p><p>在软件构件标准中，由OMG组织制定，支持跨语言、跨平台分布式对象集成的标准是（ ）。</p><ul><li>A. COM/DCOM</li><li>B. CORBA</li><li>C. EJB</li><li>D. Spring Bean</li></ul><details class="callout callout-note"><summary class="callout-title"><span class="callout-icon">📝</span>答案与解析</summary><div class="callout-body"><p>答案：B</p><p>解析：CORBA(OMG制定)=跨语言跨平台；COM/DCOM(Microsoft)=Windows平台；EJB(Sun)=Java平台。</p></div></details><hr><p><strong>[Q11] EJB会话构件</strong></p><p>EJB是企业级Java构件。其中，（ ）负责完成服务端与客户端的交互；（ ）用于数据持久化；（ ）主要用来处理并发和异步访问操作。</p><ul><li>A. 会话型构件</li><li>B. 实体型构件</li><li>C. COM构件</li><li>D. 消息驱动构件</li></ul><details class="callout callout-note"><summary class="callout-title"><span class="callout-icon">📝</span>答案与解析</summary><div class="callout-body"><p>答案：A</p><p>解析：会话Bean=客户端交互；实体Bean=数据持久化；消息驱动Bean=异步消息。</p></div></details><hr><p><strong>[Q58] 消息驱动Bean</strong></p><p>J2EE中的&quot;消息驱动Bean&quot;用于处理（ ）。</p><ul><li>A. 数据库事务</li><li>B. HTTP请求</li><li>C. 异步消息</li><li>D. 用户界面事件</li></ul><details class="callout callout-note"><summary class="callout-title"><span class="callout-icon">📝</span>答案与解析</summary><div class="callout-body"><p>答案：C</p><p>解析：消息驱动Bean(Message-Driven Bean)=处理异步消息(JMS)。</p></div></details><hr><p><strong>[Q78] EJB Bean类型</strong></p><p>关于EJB中Bean的类型，下列说法错误的是（ ）。</p><ul><li>A. Session Bean维护短暂会话</li><li>B. Entity Bean负责持久化数据</li><li>C. Message-Driven Bean只能同步接收消息</li><li>D. Session Bean在会话结束后数据消失</li></ul><details class="callout callout-note"><summary class="callout-title"><span class="callout-icon">📝</span>答案与解析</summary><div class="callout-body"><p>答案：C</p><p>解析：Message-Driven Bean是<strong>异步</strong>接收消息，不是同步。</p></div></details><hr><p><strong>[Q13] J2EE构件模型</strong></p><p>J2EE应用系统支持五种不同类型的构件模型，包括（ ）。</p><ul><li>A. Applet、JFC、JSP、Servlet、EJB</li><li>B. JNDI、IIOP、RMI、EJB、JSP/Servlet</li><li>C. JDBC、EJB、JSP、Servlet、JCA</li><li>D. Applet、Servlet、JSP、EJB、Application Client</li></ul><details class="callout callout-note"><summary class="callout-title"><span class="callout-icon">📝</span>答案与解析</summary><div class="callout-body"><p>答案：D</p><p>解析：J2EE五种构件=Applet+Servlet+JSP+EJB+Application Client。B是协议，C混入了API。</p></div></details><hr><p><strong>[Q41] 中间件-通信</strong></p><p>中间件是提供平台和应用之间的通用服务。中间件的基本功能包括：为客户端和服务器之间提供（1）；提供（2）保证交易的一致性；提供应用的（3）。</p><ul><li>A. 连接和通信</li><li>B. 应用程序接口</li><li>C. 通信协议支持</li><li>D. 数据交换标准</li></ul><details class="callout callout-note"><summary class="callout-title"><span class="callout-icon">📝</span>答案与解析</summary><div class="callout-body"><p>答案：A</p><p>解析：中间件三大功能：连接和通信、交易管理、负载均衡和高可用。</p></div></details><hr><p><strong>[Q42] 中间件-交易管理</strong></p><p>同上。提供（ ）保证交易的一致性。</p><ul><li>A. 安全控制机制</li><li>B. 交易管理机制</li><li>C. 标准消息格式</li><li>D. 数据映射机制</li></ul><details class="callout callout-note"><summary class="callout-title"><span class="callout-icon">📝</span>答案与解析</summary><div class="callout-body"><p>答案：B</p><p>解析：交易管理机制保证事务一致性（ACID）。</p></div></details><hr><p><strong>[Q43] 中间件-负载均衡</strong></p><p>同上。提供应用的（ ）。</p><ul><li>A. 基础硬件平台</li><li>B. 操作系统服务</li><li>C. 网络和数据库</li><li>D. 负载均衡和高可用性</li></ul><details class="callout callout-note"><summary class="callout-title"><span class="callout-icon">📝</span>答案与解析</summary><div class="callout-body"><p>答案：D</p><p>解析：中间件提供应用的负载均衡和高可用性。</p></div></details><hr><p><strong>[Q50] Tomcat</strong></p><p>Tomcat中间件的主要功能是（ ）。</p><ul><li>A. 管理分布式数据库</li><li>B. 提供Web应用的运行时环境</li><li>C. 实现消息队列</li><li>D. 加密网络传输</li></ul><details class="callout callout-note"><summary class="callout-title"><span class="callout-icon">📝</span>答案与解析</summary><div class="callout-body"><p>答案：B</p><p>解析：Tomcat=Web服务器中间件(Servlet容器)，提供Web应用运行时环境。</p></div></details><hr><p><strong>[Q53] 通信中间件</strong></p><p>以下（ ）是通信处理（消息）中间件的主要功能。</p><ul><li>A. 实现事务的协调处理</li><li>B. 保证系统能在不同平台之间通信</li><li>C. 提供Web程序执行的运行时容器</li><li>D. 屏蔽操作系统的安全缺陷</li></ul><details class="callout callout-note"><summary class="callout-title"><span class="callout-icon">📝</span>答案与解析</summary><div class="callout-body"><p>答案：B</p><p>解析：通信中间件=跨平台数据传输和通信。A是事务中间件，C是Web中间件。</p></div></details><hr><p><strong>[Q81] 中间件类型</strong></p><p>下列关于中间件类型的描述，错误的是（ ）。</p><ul><li>A. 通信中间件用于实现跨平台数据传输</li><li>B. 事务中间件用于实现并发事务处理</li><li>C. Web服务器中间件主要用于数据加密</li><li>D. 安全中间件提供加密和认证功能</li></ul><details class="callout callout-note"><summary class="callout-title"><span class="callout-icon">📝</span>答案与解析</summary><div class="callout-body"><p>答案：C</p><p>解析：Web服务器中间件提供运行时容器（如Tomcat），不是用来做数据加密的。</p></div></details><hr><p><strong>[Q82] 中间件位置</strong></p><p>在软件系统架构中，中间件位于（ ）。</p><ul><li>A. 应用软件之上</li><li>B. 操作系统之下</li><li>C. 操作系统之上且应用软件之下</li><li>D. 与操作系统同层</li></ul><details class="callout callout-note"><summary class="callout-title"><span class="callout-icon">📝</span>答案与解析</summary><div class="callout-body"><p>答案：C</p><p>解析：层次结构：OS → 中间件 → 应用。中间件在OS之上、应用之下。</p></div></details>',120)])])}const b=l(i,[["render",r]]);export{h as __pageData,b as default};
